-- UNA-Migration-Min-System-Version: 15.0.0-RC3
-- Studio > Designer > Splash: the default splash code becomes one the apps can show too, like their built-in splash:
-- the site page's own header and footer are data-site-only, the illustration is the __illustration__ marker. Only a
-- site that still has the previous default gets it, with either line endings (Studio saves the code with LF);
-- code an operator changed is left as it is.
UPDATE `sys_options` SET `value` = '<style>\r\n    /* Guest splash, laid out like the built-in splash of the apps. The colours follow the light and dark scheme.\r\n       The apps leave out what has data-site-only (they draw their own header and footer); the web app puts the\r\n       code in .neo-splash, between its header and footer. */\r\n    .bx-landing {\r\n        --bx-landing-muted: #e4e4e7;\r\n        --bx-landing-accent: #dbeafe;\r\n        --bx-landing-accent-fg: #1d4ed8;\r\n        --bx-landing-primary: #2563eb;\r\n        --bx-landing-title: #0a0a0c;\r\n        --bx-landing-text: #52525b;\r\n        --bx-landing-border: #e4e4e7;\r\n        display: flex;\r\n        flex-direction: column;\r\n        min-height: 100vh;\r\n    }\r\n    .dark .bx-landing,\r\n    [data-theme="dark"] .bx-landing {\r\n        --bx-landing-muted: #3f3f46;\r\n        --bx-landing-accent: #172554;\r\n        --bx-landing-accent-fg: #60a5fa;\r\n        --bx-landing-title: #fafafc;\r\n        --bx-landing-text: #a1a1aa;\r\n        --bx-landing-border: #3f3f46;\r\n    }\r\n    @media (prefers-color-scheme: dark) {\r\n        :root:not([data-theme="light"]) .neo-splash .bx-landing {\r\n            --bx-landing-muted: #3f3f46;\r\n            --bx-landing-accent: #172554;\r\n            --bx-landing-accent-fg: #60a5fa;\r\n            --bx-landing-title: #fafafc;\r\n            --bx-landing-text: #a1a1aa;\r\n            --bx-landing-border: #3f3f46;\r\n        }\r\n    }\r\n    .neo-splash .bx-landing {\r\n        flex: 1 1 auto;\r\n        min-height: 0;\r\n    }\r\n    .bx-landing-header,\r\n    .bx-landing-footer {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        align-items: center;\r\n        justify-content: space-between;\r\n        gap: 0.75rem;\r\n        padding: 0.75rem 1rem;\r\n    }\r\n    .bx-landing-header {\r\n        min-height: 4rem;\r\n        box-sizing: border-box;\r\n    }\r\n    .bx-landing-footer {\r\n        border-top: 1px solid var(--bx-landing-border);\r\n        color: var(--bx-landing-text);\r\n        font-size: 0.875rem;\r\n    }\r\n    .bx-landing-main {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 1.5rem;\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        max-width: 88rem;\r\n        margin: 0 auto;\r\n        padding: 1rem;\r\n    }\r\n    .bx-landing-intro {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 1.5rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n    .bx-landing-art {\r\n        display: block;\r\n        width: 12rem;\r\n        height: 12rem;\r\n    }\r\n    .bx-landing-title {\r\n        margin: 0;\r\n        color: var(--bx-landing-title);\r\n        font-size: 2.25rem;\r\n        font-weight: 700;\r\n        line-height: 1.25;\r\n        letter-spacing: -0.025em;\r\n        text-wrap: balance;\r\n    }\r\n    .bx-landing-text {\r\n        max-width: 48rem;\r\n        margin: 0;\r\n        color: var(--bx-landing-text);\r\n        font-size: 1rem;\r\n        line-height: 1.5rem;\r\n        text-wrap: pretty;\r\n    }\r\n    .bx-landing-auth {\r\n        flex: none;\r\n        width: 100%;\r\n        max-width: 28rem;\r\n    }\r\n    .bx-landing-links {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        gap: 1rem;\r\n    }\r\n    @media (min-width: 640px) {\r\n        .bx-landing-main { padding: 1.5rem; }\r\n        .bx-landing-text { font-size: 1.125rem; line-height: 1.75rem; }\r\n    }\r\n    @media (min-width: 1024px) {\r\n        .bx-landing-main {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n            padding: 3rem;\r\n        }\r\n        .bx-landing-intro {\r\n            align-items: flex-start;\r\n            text-align: start;\r\n        }\r\n    }\r\n    @media (min-width: 1280px) {\r\n        .bx-landing-title { font-size: 3rem; }\r\n    }\r\n</style>\r\n<div class="bx-landing bx-def-color-bg-page">\r\n    <header class="bx-landing-header" data-site-only>\r\n        __logo__\r\n        <a class="bx-btn bx-btn-primary" href="__join_link__"><bx_text:_sys_txt_splash_join /></a>\r\n    </header>\r\n    <main class="bx-landing-main">\r\n        <div class="bx-landing-intro text-center">\r\n            __illustration__\r\n            <h1 class="bx-landing-title"><bx_text:_sys_txt_splash_title /></h1>\r\n            <p class="bx-landing-text"><bx_text:_sys_txt_splash_slogan /></p>\r\n        </div>\r\n        <div class="bx-landing-auth">__login_form_in_box__</div>\r\n    </main>\r\n    <footer class="bx-landing-footer" data-site-only>\r\n        <nav class="bx-landing-links">\r\n            <a href="<bx_url_root />page.php?i=terms"><bx_text:_sys_menu_item_title_terms /></a>\r\n            <a href="<bx_url_root />page.php?i=privacy"><bx_text:_sys_menu_item_title_privacy /></a>\r\n        </nav>\r\n        <span>&copy; {site_title}</span>\r\n    </footer>\r\n</div>'
WHERE `name` = 'sys_site_splash_code' AND REPLACE(`value`, '\r', '') = REPLACE('<style>\r\n    /* Landing page, laid out like the NEO guest home. The shape colours follow the light and dark scheme. */\r\n    .bx-landing {\r\n        --bx-landing-muted: #e4e4e7;\r\n        --bx-landing-accent: #dbeafe;\r\n        --bx-landing-accent-fg: #1d4ed8;\r\n        --bx-landing-primary: #2563eb;\r\n        --bx-landing-title: #09090b;\r\n        --bx-landing-border: #e4e4e7;\r\n        display: flex;\r\n        flex-direction: column;\r\n        min-height: 100vh;\r\n    }\r\n    .dark .bx-landing {\r\n        --bx-landing-muted: #3f3f46;\r\n        --bx-landing-accent: #172554;\r\n        --bx-landing-accent-fg: #60a5fa;\r\n        --bx-landing-title: #fafafa;\r\n        --bx-landing-border: #3f3f46;\r\n    }\r\n    .bx-landing-header,\r\n    .bx-landing-footer {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        align-items: center;\r\n        justify-content: space-between;\r\n        gap: 0.75rem;\r\n        padding: 0.75rem 1rem;\r\n    }\r\n    .bx-landing-header {\r\n        min-height: 4rem;\r\n        box-sizing: border-box;\r\n    }\r\n    .bx-landing-footer {\r\n        border-top: 1px solid var(--bx-landing-border);\r\n        font-size: 0.875rem;\r\n    }\r\n    .bx-landing-main {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 1.5rem;\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        max-width: 88rem;\r\n        margin: 0 auto;\r\n        padding: 1.5rem;\r\n    }\r\n    .bx-landing-intro {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 1.5rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n    .bx-landing-art {\r\n        display: block;\r\n        width: 12rem;\r\n        height: 12rem;\r\n    }\r\n    .bx-landing-muted { fill: var(--bx-landing-muted); }\r\n    .bx-landing-accent { fill: var(--bx-landing-accent); }\r\n    .bx-landing-accent-fg { fill: var(--bx-landing-accent-fg); }\r\n    .bx-landing-primary { fill: var(--bx-landing-primary); }\r\n    .bx-landing-title {\r\n        margin: 0;\r\n        color: var(--bx-landing-title);\r\n        font-size: 2.25rem;\r\n        font-weight: 700;\r\n        line-height: 1.1;\r\n        letter-spacing: -0.025em;\r\n        text-wrap: balance;\r\n    }\r\n    .bx-landing-text {\r\n        max-width: 48rem;\r\n        margin: 0;\r\n        font-size: 1rem;\r\n        line-height: 1.5;\r\n        text-wrap: pretty;\r\n    }\r\n    .bx-landing-auth {\r\n        flex: none;\r\n        width: 100%;\r\n        max-width: 24rem;\r\n    }\r\n    .bx-landing-links {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        gap: 1rem;\r\n    }\r\n    @media (min-width: 640px) {\r\n        .bx-landing-title { font-size: 3rem; }\r\n        .bx-landing-text { font-size: 1.125rem; }\r\n    }\r\n    @media (min-width: 1024px) {\r\n        .bx-landing-main {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n            padding: 3rem;\r\n        }\r\n        .bx-landing-intro {\r\n            align-items: flex-start;\r\n            text-align: start;\r\n        }\r\n    }\r\n</style>\r\n<div class="bx-landing bx-def-color-bg-page">\r\n    <header class="bx-landing-header">\r\n        __logo__\r\n        <a class="bx-btn bx-btn-primary" href="__join_link__"><bx_text:_sys_txt_splash_join /></a>\r\n    </header>\r\n    <main class="bx-landing-main">\r\n        <div class="bx-landing-intro">\r\n            <svg class="bx-landing-art" viewBox="0 0 200 200" aria-hidden="true" focusable="false">\r\n                <path class="bx-landing-muted" d="M28 4H72A24 24 0 0 1 96 28V72A24 24 0 0 1 72 96H28A24 24 0 0 1 4 72V28A24 24 0 0 1 28 4Z" />\r\n                <path class="bx-landing-primary" d="M24 50a26 26 0 1 0 52 0a26 26 0 1 0 -52 0Z" />\r\n                <path class="bx-landing-accent" d="M104 96V4A92 92 0 0 1 196 96Z" />\r\n                <path class="bx-landing-accent-fg" d="M168 20a12 12 0 1 0 24 0a12 12 0 1 0 -24 0Z" />\r\n                <path class="bx-landing-accent-fg" d="M4 104A46 46 0 0 0 96 104Z" />\r\n                <path class="bx-landing-muted" d="M4 196A46 46 0 0 1 96 196Z" />\r\n                <path class="bx-landing-muted" d="M104 150a46 46 0 1 0 92 0a46 46 0 1 0 -92 0ZM120 150a30 30 0 1 0 60 0a30 30 0 1 0 -60 0Z" fill-rule="evenodd" />\r\n                <path class="bx-landing-primary" d="M134 150a16 16 0 1 0 32 0a16 16 0 1 0 -32 0Z" />\r\n            </svg>\r\n            <h1 class="bx-landing-title"><bx_text:_sys_txt_splash_title /></h1>\r\n            <p class="bx-landing-text bx-def-font-grayed"><bx_text:_sys_txt_splash_slogan /></p>\r\n        </div>\r\n        <div class="bx-landing-auth">__login_form_in_box__</div>\r\n    </main>\r\n    <footer class="bx-landing-footer bx-def-font-grayed">\r\n        <nav class="bx-landing-links">\r\n            <a href="<bx_url_root />page.php?i=terms"><bx_text:_sys_menu_item_title_terms /></a>\r\n            <a href="<bx_url_root />page.php?i=privacy"><bx_text:_sys_menu_item_title_privacy /></a>\r\n        </nav>\r\n        <span>&copy; {site_title}</span>\r\n    </footer>\r\n</div>', '\r', '');
